'use client';

import React, { useState } from 'react';

const VEHICLES = [
  { id: 'auto', name: 'Auto', icon: 'fa-solid fa-motorcycle', emoji: '🛺' },
  { id: 'mini', name: 'Mini (Prime Sedan)', icon: 'fa-solid fa-car', emoji: '🚕' },
  { id: 'suv', name: 'Prime SUV', icon: 'fa-solid fa-car-side', emoji: '🚙' },
  { id: 'bus', name: 'Bus', icon: 'fa-solid fa-bus', emoji: '🚌' },
  { id: 'truck', name: 'Truck', icon: 'fa-solid fa-truck', emoji: '🚚' },
  { id: 'towing', name: 'Towing & Recovery', icon: 'fa-solid fa-truck-pickup', emoji: '🚜' },
  { id: 'unreserved', name: 'Unreserved', icon: 'fa-solid fa-ticket', emoji: '🎟️' },
];

interface RideBookingModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function RideBookingModal({ isOpen, onClose }: RideBookingModalProps) {
  const [selectedVehicle, setSelectedVehicle] = useState('mini');

  if (!isOpen) return null;

  return (
    <div className="modal-overlay open" style={{ display: 'flex', zIndex: 1000 }} onClick={onClose}>
      <div className="modal-content" style={{ maxWidth: '900px', width: '90%', padding: '30px', background: '#ffffff', color: '#111827' }} onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <h2 style={{ color: '#111827' }}>Book a Ride</h2>
          <button className="close-btn" onClick={onClose}><i className="fa-solid fa-xmark"></i></button>
        </div>
        
        <div className="modal-body">
          {/* Vehicle Horizontal Selector */}
          <div className="vehicle-selector-container">
            {VEHICLES.map(v => (
              <div 
                key={v.id} 
                className={`vehicle-item ${selectedVehicle === v.id ? 'active' : ''}`}
                onClick={() => setSelectedVehicle(v.id)}
              >
                <div className="vehicle-icon-wrapper">
                  <span style={{ fontSize: '24px' }}>{v.emoji}</span>
                </div>
                <span className="vehicle-name">{v.name}</span>
              </div>
            ))}
          </div>

          {/* Booking Form Grid */}
          <div className="booking-form-grid">
            <div className="form-group">
              <label style={{ color: '#4b5563' }}>Pickup Location</label>
              <div className="input-with-icon">
                <i className="fa-solid fa-location-dot" style={{ color: '#10b981' }}></i>
                <input type="text" placeholder="Enter pickup location" defaultValue="Current Location" style={{ background: '#f9fafb', color: '#111827', border: '1px solid #d1d5db' }} />
              </div>
            </div>

            <div className="form-group">
              <label style={{ color: '#4b5563' }}>Drop Location</label>
              <div className="input-with-icon">
                <i className="fa-solid fa-location-dot" style={{ color: '#ef4444' }}></i>
                <input type="text" placeholder="Enter destination" style={{ background: '#f9fafb', color: '#111827', border: '1px solid #d1d5db' }} />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group" style={{ flex: 1 }}>
                <label style={{ color: '#4b5563' }}>Date</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-calendar-day" style={{ color: '#6b7280' }}></i>
                  <input type="date" style={{ background: '#f9fafb', color: '#111827', border: '1px solid #d1d5db' }} />
                </div>
              </div>
              <div className="form-group" style={{ flex: 1 }}>
                <label style={{ color: '#4b5563' }}>Time</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-clock" style={{ color: '#6b7280' }}></i>
                  <input type="time" style={{ background: '#f9fafb', color: '#111827', border: '1px solid #d1d5db' }} />
                </div>
              </div>
            </div>

            <button className="search-rides-btn">
              Search Rides <i className="fa-solid fa-arrow-right"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
